 exit:
        gf_bs_del(bs);
        if (sps_data_without_emulation_bytes) gf_free(sps_data_without_emulation_bytes);
        return sps_id;
 }

 static s32 gf_avc_read_pps_bs_internal(GF_BitStream *bs, AVCState *avc, u32 nal_hdr)
